            "activity_name": "U3: Externalize ccprovider Structures",
            "activity_description": "Replace internal ccprovider structures with direct dependency. Update chaincode provider related code.",
            "most_likely_effort": 1.0
        },
        {
            "activity_id": "A5",
            "activity_name": "U4: Externalize ledger Structures",
            "activity_description": "Replace internal ledger structures with direct dependency. Update ledger-related SDK components.",
            "most_likely_effort": 1.0
        },
        {
            "activity_id": "A6",
            "activity_name": "U5: Externalize Common Utilities",
            "activity_description": "Replace internal common utilities (both common and core paths) with external dependencies. This may involve multiple packages.",
            "most_likely_effort": 2.0
        },
        {
            "activity_id": "A7",
            "activity_name": "U6: Implement Temporary Go.mod Workaround",
            "activity_description": "Implement temporary logic to honor go.mod files in chaincode packages during packaging. This is a short-lived solution.",
            "most_likely_effort": 1.0
        },
        {
            "activity_id": "A8",
            "activity_name": "U7: Externalize configtxgen Functions",
            "activity_description": "Replace internal configtxgen functions with direct dependency. Update channel configuration generation code.",
            "most_likely_effort": 1.5
        },
        {
            "activity_id": "A9",
            "activity_name": "U8: Externalize configtxlator Functions",
            "activity_description": "Replace internal configtxlator functions with direct dependency. Update channel configuration translation code.",
            "most_likely_effort": 1.5
        },
        {
            "activity_id": "A10",
            "activity_name": "Dependency Management Updates",
            "activity_description": "Update go.mod file with new dependencies, remove internal copies, run dependency tidying, and verify module versions.",
            "most_likely_effort": 1.0
        },
        {
            "activity_id": "A11",
            "activity_name": "Integration Testing",
            "activity_description": "Run comprehensive SDK tests to ensure all functionalities work correctly with external dependencies. Fix any import or compatibility issues.",
            "most_likely_effort": 3.0
        },
        {
            "activity_id": "A12",
            "activity_name": "Documentation and Cleanup",
            "activity_description": "Update relevant documentation, remove internal code copies, clean up any temporary files, and prepare for release.",
            "most_likely_effort": 1.0
        }
    ],
